INSERT INTO `blog` (`id`, `content`, `created_date`, `description`, `image_banner`, `meta_description`, `num_view`, `seo_title`, `slug`, `title`, `update_date`, `user_id`) VALUES
(1, '<blockquote>\r\n<h3>2.1. Đ&uacute;ng mặt s&acirc;n</h3>\r\n<p>Mặt s&acirc;n quyết định loại đinh gi&agrave;y. Chọn sai mặt s&acirc;n l&agrave; c&ocirc;ng thức &ldquo;chuẩn&rdquo; cho trơn trượt hoặc chấn thương:</p>\r\n<ul>\r\n<li><strong>TF</strong>: Đế đinh thấp, d&agrave;y &ndash; chuy&ecirc;n cho s&acirc;n cỏ nh&acirc;n tạo 5/7 người.</li>\r\n<li><strong>AG</strong>: Đế đinh cao hơn TF, chuy&ecirc;n cho cỏ nh&acirc;n tạo chuẩn, mật độ đinh tối ưu.</li>\r\n<li><strong>FG</strong>: Đinh d&agrave;i, thưa, d&ugrave;ng cho s&acirc;n cỏ tự nhi&ecirc;n kh&ocirc;, chắc.</li>\r\n<li><strong>SG</strong>: Đinh kim loại/nhựa d&agrave;i, d&ugrave;ng cho s&acirc;n cỏ tự nhi&ecirc;n mềm, trơn.</li>\r\n<li><strong>IC/Futsal</strong>: Đế bằng, d&ugrave;ng cho s&acirc;n trong nh&agrave;, xi măng, gỗ, futsal.</li>\r\n</ul>\r\n<p>Nếu chưa r&otilde; sự kh&aacute;c nhau, bạn c&oacute; thể đọc th&ecirc;m b&agrave;i tổng hợp về mặt s&acirc;n v&agrave; loại đinh:&nbsp;<a href=\"https://thegioibongda.net/cach-chon-giay-bong-da-phu-hop-voi-tung-mat-san-thi-dau-n59220.html\" target=\"_blank\" rel=\"noreferrer noopener\">C&aacute;ch chọn gi&agrave;y b&oacute;ng đ&aacute; ph&ugrave; hợp với từng mặt s&acirc;n thi đấu&nbsp;</a>.</p>\r\n<h3>2.2. Đ&uacute;ng form ch&acirc;n</h3>\r\n<p>Ch&acirc;n mỗi người kh&aacute;c nhau: c&oacute; anh em ch&acirc;n b&egrave;, c&oacute; người ch&acirc;n thon, mu d&agrave;y, mu mỏng. Một đ&ocirc;i gi&agrave;y &ldquo;hot&rdquo; chưa chắc đ&atilde; hợp với ch&acirc;n bạn. Đ&uacute;ng form ch&acirc;n sẽ gi&uacute;p:</p>\r\n<ul>\r\n<li>Giảm đau g&oacute;t, đau mu b&agrave;n ch&acirc;n, hạn chế phồng rộp.</li>\r\n<li>&Ocirc;m ch&acirc;n vừa đủ để bứt tốc, đổi hướng tự tin.</li>\r\n<li>Tăng cảm gi&aacute;c b&oacute;ng v&igrave; b&agrave;n ch&acirc;n kh&ocirc;ng bị &ldquo;bơi&rdquo; trong gi&agrave;y.</li>\r\n</ul>\r\n<h3>2.3. Đ&uacute;ng nhu cầu &amp; ng&acirc;n s&aacute;ch</h3>\r\n<p>Kh&ocirc;ng phải ai cũng cần đ&ocirc;i gi&agrave;y v&agrave;i triệu. Nếu bạn đ&aacute; 1&ndash;2 buổi/tuần, chơi phong tr&agrave;o, c&oacute; thể chọn ph&acirc;n kh&uacute;c vừa t&uacute;i tiền nhưng vẫn đảm bảo độ bền, độ &ocirc;m v&agrave; b&aacute;m s&acirc;n tốt. Ngược lại, nếu bạn đ&aacute; nhiều, tham gia giải, ghiền cảm gi&aacute;c b&oacute;ng thật, h&atilde;y đầu tư ph&acirc;n kh&uacute;c cao hơn &ndash; đ&ocirc;i gi&agrave;y sẽ &ldquo;trả lại&rdquo; bạn bằng trải nghiệm rất kh&aacute;c.</p>\r\n</blockquote>', '2025-09-01 21:03:19.096135', 'Một đôi giày phù hợp không biến bạn thành cầu thủ chuyên nghiệp sau một đêm, nhưng chắc chắn giúp bạn chạy tự tin hơn, chạm bóng chắc hơn và giảm tối đa khó chịu ở chân', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1773384967/djrzjz1yme4wt51feyxg.jpg', 'Một đôi giày phù hợp không biến bạn thành cầu thủ chuyên nghiệp sau một đêm, nhưng chắc chắn giúp bạn chạy tự tin hơn, chạm bóng chắc hơn và giảm tối đa khó chịu ở chân', 0, ' Giới thiệu: Vì sao chọn giày đá bóng lại quan trọng?', '-gioi-thieu-vi-sao-chon-giay-a-bong-lai-quan-trong', ' Giới thiệu: Vì sao chọn giày đá bóng lại quan trọng?', '2026-03-13 13:57:44.498660', NULL),
(3, '<h2><span id=\"cau-chuyen\">2. C&acirc;u chuyện Messi v&agrave; F50 &ndash; Tốc độ c&oacute; kiểm so&aacute;t</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260226_Lv55c6jl.jpg\" alt=\"Adidas F50 Messi 3\" width=\"1000\" height=\"573\" />\r\n<figcaption>Adidas F50 Messi</figcaption>\r\n</figure>\r\n<p>Trong giai đoạn đỉnh cao sự nghiệp, Messi từng gắn b&oacute; với F50 v&agrave; tạo n&ecirc;n những m&ugrave;a giải b&ugrave;ng nổ. Nhưng điều đặc biệt l&agrave; Messi kh&ocirc;ng phải mẫu cầu thủ &ldquo;chạy thẳng v&agrave; bứt ph&aacute;&rdquo; thuần tốc độ.</p>\r\n<p>Phong c&aacute;ch của anh l&agrave; giữ b&oacute;ng s&aacute;t ch&acirc;n, r&ecirc; trong kh&ocirc;ng gian hẹp, tăng tốc ngắn li&ecirc;n tục v&agrave; đổi hướng cực nhanh. Ch&iacute;nh v&igrave; vậy, F50 Messi kh&ocirc;ng chỉ cần nhẹ &ndash; m&agrave; phải phản hồi nhanh v&agrave; giữ được cảm gi&aacute;c b&oacute;ng ch&iacute;nh x&aacute;c.</p>\r\n<p>Triết l&yacute; đ&oacute; được t&aacute;i hiện tr&ecirc;n thế hệ F50 Messi mới: speed nhưng kh&ocirc;ng đ&aacute;nh đổi khả năng kiểm so&aacute;t.</p>\r\n<h2><span id=\"cong-nghe\">3. C&ocirc;ng nghệ tr&ecirc;n Adidas F50 Messi thế hệ mới</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260226_eljRvukJ.jpg\" alt=\"Adidas F50 Messi 4\" width=\"1000\" height=\"725\" />\r\n<figcaption>Adidas F50 Messi</figcaption>\r\n</figure>\r\n<h3>Fibertouch Upper</h3>\r\n<p>Upper Fibertouch dạng mesh tổng hợp cho cảm gi&aacute;c b&oacute;ng trực diện. Khi r&ecirc; b&oacute;ng ở tốc độ cao, lớp vật liệu n&agrave;y gi&uacute;p phản hồi nhanh v&agrave; r&otilde; lực.</p>\r\n<h3>Sprintweb Texturing</h3>\r\n<p>Bề mặt phủ v&acirc;n nổi Sprintweb tăng ma s&aacute;t khi xử l&yacute; b&oacute;ng, hỗ trợ những pha đảo hướng nhanh &ndash; đ&uacute;ng phong c&aacute;ch Messi.</p>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260226_6Bm3hqNC.jpg\" alt=\"Adidas F50 Messi 5\" width=\"1000\" height=\"725\" />\r\n<figcaption>Adidas F50 Messi</figcaption>\r\n</figure>\r\n<h3>Sprintframe 360</h3>\r\n<p>Bộ đế Sprintframe 360 với cấu tr&uacute;c đinh b&aacute;n n&oacute;n kết hợp lưỡi dao hỗ trợ xoay trụ đa hướng. Điều n&agrave;y đặc biệt hữu &iacute;ch khi r&ecirc; b&oacute;ng v&agrave; cắt v&agrave;o trung lộ.</p>\r\n<p>Một số phi&ecirc;n bản cao cấp c&ograve;n t&iacute;ch hợp Lightstrike Pro ở phần forefoot gi&uacute;p tăng độ bật khi tăng tốc ngắn.</p>\r\n<p>Tổng thể, F50 Messi vẫn giữ DNA speed boot, nhưng cảm gi&aacute;c b&oacute;ng c&oacute; xu hướng &ldquo;mềm&rdquo; v&agrave; kiểm so&aacute;t hơn so với nhiều speed boot thuần kh&aacute;c.</p>\r\n<h2><span id=\"so-sanh\">4. So s&aacute;nh F50 Messi Elite &ndash; Pro &ndash; League</span></h2>\r\n<h3>F50 Messi Elite</h3>\r\n<p>Phi&ecirc;n bản cao cấp nhất, ho&agrave;n thiện chi tiết tốt nhất, upper mỏng v&agrave; phản hồi r&otilde;. Ph&ugrave; hợp người chơi cường độ cao, muốn cảm gi&aacute;c locked-in tối đa.</p>\r\n<h3>F50 Messi Pro</h3>\r\n<p>Giữ lại phần lớn nền tảng c&ocirc;ng nghệ nhưng tối ưu gi&aacute; th&agrave;nh. Tương tự như triết l&yacute; của&nbsp;<a href=\"https://thegioibongda.net/adidas-f50-pro-tf-pc566123.html\">Adidas F50 Pro</a>, đ&acirc;y thường l&agrave; lựa chọn c&acirc;n bằng giữa hiệu năng v&agrave; ng&acirc;n s&aacute;ch.</p>\r\n<h3>F50 Messi League</h3>\r\n<p>Phi&ecirc;n bản dễ tiếp cận hơn, ph&ugrave; hợp học sinh &ndash; sinh vi&ecirc;n hoặc người chơi phong tr&agrave;o. C&aacute;ch ph&acirc;n cấp tương tự d&ograve;ng&nbsp;<a href=\"https://thegioibongda.net/adidas-f50-league-tf-pc566124.html\">Adidas F50 League</a>, nhưng mang thiết kế Messi.</p>\r\n<p>Trong c&aacute;c buổi tư vấn thực tế tại cửa h&agrave;ng, phi&ecirc;n bản Pro thường l&agrave; lựa chọn hợp l&yacute; nhất cho s&acirc;n 7 Việt Nam &ndash; vừa đủ c&ocirc;ng nghệ, vừa tối ưu chi ph&iacute;.</p>\r\n<h2><span id=\"phu-hop\">5. Ai n&ecirc;n chọn Adidas F50 Messi?</span></h2>\r\n<ul>\r\n<li>Cầu thủ r&ecirc; dắt, th&iacute;ch xử l&yacute; b&oacute;ng trong phạm vi hẹp</li>\r\n<li>Người chơi đ&aacute; bi&ecirc;n hoặc tiền đạo nhỏ con thi&ecirc;n kỹ thuật</li>\r\n<li>Anh em th&iacute;ch cảm gi&aacute;c b&oacute;ng r&otilde;, phản hồi nhanh</li>\r\n</ul>\r\n<p>Kh&ocirc;ng ph&ugrave; hợp nếu:</p>\r\n<ul>\r\n<li>Bạn c&oacute; b&agrave;n ch&acirc;n qu&aacute; b&egrave; ngang</li>\r\n<li>Ưu ti&ecirc;n độ &ecirc;m d&agrave;y như d&ograve;ng kiểm so&aacute;t truyền thống</li>\r\n</ul>\r\n<p>Nếu đang t&igrave;m một đ&ocirc;i&nbsp;<a href=\"https://thegioibongda.net/\">gi&agrave;y b&oacute;ng đ&aacute;</a>&nbsp;thi&ecirc;n về kỹ thuật v&agrave; tăng tốc ngắn, F50 Messi l&agrave; lựa chọn rất đ&aacute;ng c&acirc;n nhắc.</p>\r\n<h2><span id=\"ket-noi-silo\">6. C&aacute;c b&agrave;i chi tiết về F50 Messi</span></h2>\r\n<ul>\r\n<li>Đ&aacute;nh gi&aacute; chi tiết F50 Messi Elite</li>\r\n<li>Ph&acirc;n t&iacute;ch hiệu năng F50 Messi Pro s&acirc;n 7</li>\r\n<li>Cảm nhận thực tế F50 Messi League phong tr&agrave;o</li>\r\n<li>So s&aacute;nh F50 Messi v&agrave; F50 thường</li>\r\n</ul>', '2025-09-03 14:22:46.775864', 'Nhiều anh em nghĩ F50 Messi chỉ khác ở phối màu. Thực tế, đây là phiên bản mang dấu ấn cá nhân của Lionel Messi, từ thiết kế đồ họa, màu sắc đến tinh thần chơi bóng mà đôi giày hướng tới.', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1773385157/rxmgrzwbvdv5t1bqdpmw.jpg', 'Nhiều anh em nghĩ F50 Messi chỉ khác ở phối màu. Thực tế, đây là phiên bản mang dấu ấn cá nhân của Lionel Messi, từ thiết kế đồ họa, màu sắc đến tinh thần chơi bóng mà đôi giày hướng tới.', 0, 'Adidas F50 Messi – Di sản tốc độ mang dấu ấn của một huyền thoại', 'adidas-f50-messi-di-san-toc-o-mang-dau-an-cua-mot-huyen-thoai', 'Adidas F50 Messi – Di sản tốc độ mang dấu ấn của một huyền thoại', '2026-03-13 13:59:46.200364', NULL),
(5, '<section class=\"right-content col-lg-9 col-12 mx-auto\">\r\n<article class=\"article-main\">\r\n<div class=\"article-details\">\r\n<div class=\"article-content js-toc-content\">\r\n<div id=\"ega-uti-editable-content\" class=\"rte\" data-platform=\"haravan\" data-id=\"1002600538\" data-blog-id=\"1000950832\">\r\n<h1 style=\"text-align: center;\">Mizuno &lsquo;Blazing Flair&rsquo; Pack &ndash; &ldquo;Ignite The Pitch&rdquo; v&agrave; sắc hồng kiểu Nhật</h1>\r\n<div class=\"title-main-home\">\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_1pTdHK18.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack\" width=\"1000\" height=\"437\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack</figcaption>\r\n</figure>\r\n<div id=\"toc_container\" class=\"no_bullets\">\r\n<p class=\"toc_title\" style=\"text-align: center;\"><strong>Mục lục</strong></p>\r\n<p style=\"text-align: center;\">1. Giới thiệu Blazing Flair Pack</p>\r\n<p style=\"text-align: center;\">2. Concept &ldquo;Ignite The Pitch&rdquo;: hiệu ứng bản đồ nhiệt v&agrave; tinh thần bứt ph&aacute;</p>\r\n<p style=\"text-align: center;\">3. M&agrave;u sắc White/Pink Tetra/Fuchsia Purple: nổi bật nhưng kh&ocirc;ng &ldquo;lố&rdquo;</p>\r\n<p style=\"text-align: center;\">4. Alpha 3: nhanh, &ocirc;m ch&acirc;n v&agrave; sinh ra cho những pha tăng tốc</p>\r\n<p style=\"text-align: center;\">5. Morelia Neo 4: Kaizen &ndash; tinh chỉnh từng chi tiết, giữ chất K-Leather</p>\r\n<p style=\"text-align: center;\">6. Gợi &yacute; chọn nhanh: bạn hợp Alpha hay Morelia Neo?</p>\r\n</div>\r\n<h2><span id=\"gioi-thieu\">1. Giới thiệu Blazing Flair Pack</span></h2>\r\n<div>\r\n<p style=\"text-align: center;\"><iframe src=\"https://www.youtube.com/embed/STx-qafhxFw\" width=\"1000\" height=\"700\" frameborder=\"0\" data-mce-fragment=\"1\"></iframe></p>\r\n</div>\r\n<p>Mizuno vừa &ldquo;đ&aacute;nh thức&rdquo; s&acirc;n cỏ với bộ sưu tập mới mang t&ecirc;n&nbsp;<strong>Blazing Flair</strong>&nbsp;&ndash; một pack đ&uacute;ng kiểu&nbsp;<strong>mạnh năng lượng, mạnh c&aacute; t&iacute;nh</strong>, nhưng vẫn giữ c&aacute;i chất rất Mizuno: vừa c&oacute; di sản, vừa c&oacute; hiệu năng, v&agrave; ho&agrave;n thiện tỉ mỉ đến mức kh&oacute; bắt bẻ.</p>\r\n<p>Blazing Flair quy tụ hai d&ograve;ng được quan t&acirc;m nhất hiện tại của Mizuno:&nbsp;<strong>Alpha 3</strong>&nbsp;(thi&ecirc;n về tốc độ) v&agrave;&nbsp;<strong>Morelia Neo 4</strong>&nbsp;(thi&ecirc;n cảm gi&aacute;c b&oacute;ng &ndash; di sản). Nếu bạn đang t&igrave;m một đ&ocirc;i&nbsp;gi&agrave;y đ&aacute; b&oacute;ng Mizuno&nbsp;nổi bật khi ra s&acirc;n nhưng vẫn &ldquo;đ&uacute;ng b&agrave;i&rdquo; để đ&aacute; thật, pack n&agrave;y l&agrave; c&aacute;i t&ecirc;n rất đ&aacute;ng thử.</p>\r\n<h2><span id=\"concept\">2. Concept &ldquo;Ignite The Pitch&rdquo;: hiệu ứng bản đồ nhiệt v&agrave; tinh thần bứt ph&aacute;</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_KX47xSH9.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack 2\" width=\"1000\" height=\"725\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack</figcaption>\r\n</figure>\r\n<p>Điểm khiến Blazing Flair &ldquo;c&oacute; hồn&rdquo; kh&ocirc;ng chỉ nằm ở phối m&agrave;u, m&agrave; ở concept Mizuno x&acirc;y dựng cho cả pack:&nbsp;<strong>IGNITE THE PITCH</strong>. Hiểu đơn giản, đ&acirc;y l&agrave; c&acirc;u chuyện về&nbsp;<strong>nhiệt lượng</strong>&nbsp;&ndash; nhiệt của cơ thể, nhiệt của nhịp độ trận đấu, v&agrave; nhiệt của tham vọng khi bạn tăng tốc.</p>\r\n<p>Mizuno d&ugrave;ng cảm hứng&nbsp;<strong>infrared (hồng ngoại)</strong>&nbsp;để tạo cảm gi&aacute;c như một&nbsp;<strong>heat mapping</strong>&nbsp;(bản đồ nhiệt): mỗi bước chạy l&agrave; một lần &ldquo;đốt&rdquo; s&acirc;n, c&agrave;ng v&agrave;o trận c&agrave;ng n&oacute;ng, c&agrave;ng gắt, c&agrave;ng b&ugrave;ng. V&agrave; khi game l&ecirc;n cao tr&agrave;o, pack n&agrave;y nhắc bạn một điều:&nbsp;<strong>đừng n&eacute; nhiệt &ndash; h&atilde;y embrace the heat</strong>.</p>\r\n<p>Blazing Flair cũng l&agrave; một&nbsp;<strong>fiery statement</strong>&nbsp;d&agrave;nh cho những cầu thủ th&iacute;ch ph&aacute; giới hạn: d&aacute;m thể hiện, d&aacute;m kh&aacute;c biệt, d&aacute;m đ&aacute; theo c&aacute;ch của m&igrave;nh. M&agrave;u hồng &ndash; cam &ndash; t&iacute;m kh&ocirc;ng chỉ để nổi bật, m&agrave; để phản chiếu tinh thần&nbsp;<strong>fearless pursuit</strong>: theo đuổi sự tốt hơn một c&aacute;ch kh&ocirc;ng sợ h&atilde;i.</p>\r\n<h2><span id=\"mau-sac\">3. M&agrave;u sắc White/Pink Tetra/Fuchsia Purple: nổi bật nhưng kh&ocirc;ng &ldquo;lố&rdquo;</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_8j5fzCNn.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack 3\" width=\"1000\" height=\"725\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack</figcaption>\r\n</figure>\r\n<p>Blazing Flair xuất hiện trong bảng m&agrave;u&nbsp;<strong>White/Pink Tetra/Fuchsia Purple</strong>: nền trắng s&aacute;ng, phủ l&ecirc;n c&aacute;c mảng chuyển sắc hồng &ndash; t&iacute;m kiểu &ldquo;ch&aacute;y nhiệt&rdquo;. Nh&igrave;n ngo&agrave;i đời sẽ c&oacute; cảm gi&aacute;c&nbsp;<strong>ăn đ&egrave;n rất tốt</strong>, đặc biệt khi đ&aacute; s&acirc;n tối hoặc s&acirc;n c&oacute; đ&egrave;n mạnh.</p>\r\n<p>Điều hay l&agrave; Mizuno giữ được sự c&acirc;n bằng. D&ugrave; m&agrave;u nổi, tổng thể vẫn sạch v&agrave; dễ phối đồ s&acirc;n. Quan trọng hơn: mỗi silo &ldquo;dịch&rdquo; bảng m&agrave;u theo c&aacute;ch ri&ecirc;ng: Alpha 3 nh&igrave;n hiện đại, tốc độ; Morelia Neo 4 vẫn tối giản cổ điển nhưng được n&acirc;ng mood r&otilde; rệt.</p>\r\n<h2><span id=\"alpha-3\">4. Alpha 3: nhanh, &ocirc;m ch&acirc;n v&agrave; sinh ra cho những pha tăng tốc</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_9JzKdH9b.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack Alpha 3\" width=\"1000\" height=\"505\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack Alpha 3</figcaption>\r\n</figure>\r\n<p>T&acirc;m điểm của pack l&agrave;&nbsp;<strong>Alpha 3</strong>&nbsp;&ndash; d&ograve;ng &ldquo;fast&rdquo; của Mizuno với triết l&yacute; rất thẳng: đ&ocirc;i gi&agrave;y phải&nbsp;<strong>&ocirc;m ch&acirc;n như một phần cơ thể</strong>&nbsp;để bạn tăng tốc, đổi hướng tự nhi&ecirc;n v&agrave; gọn hơn.</p>\r\n<p>Điểm n&acirc;ng cấp đ&aacute;ng ch&uacute; &yacute; l&agrave;&nbsp;<strong>upper knit mới</strong>, được Mizuno ph&aacute;t triển để tạo cảm gi&aacute;c nhẹ, mềm v&agrave; &ldquo;adapt&rdquo; tốt khi ch&acirc;n hoạt động li&ecirc;n tục. Upper được gia cố bằng c&aacute;c đường kh&acirc;u ch&iacute;nh x&aacute;c, gi&uacute;p giữ form &ocirc;m v&agrave; hỗ trợ vừa đủ khi bạn bứt hoặc quặt gấp.</p>\r\n<p>Ở ph&iacute;a dưới, lớp đệm&nbsp;<strong>Mizuno Enerzy</strong>&nbsp;gi&uacute;p đ&ocirc;i gi&agrave;y c&oacute; độ &ecirc;m v&agrave; độ nảy dễ chịu hơn, đặc biệt hữu &iacute;ch với anh em đ&aacute; tốc độ cao nhưng vẫn muốn ch&acirc;n kh&ocirc;ng bị &ldquo;gắt&rdquo; sau 60&ndash;90 ph&uacute;t.</p>\r\n<p>Nếu bạn l&agrave; kiểu cầu thủ chạy c&aacute;nh, tiền đạo, hoặc đ&aacute; s&acirc;n 7 cần pressing v&agrave; di chuyển rộng, Alpha 3 l&agrave; lựa chọn rất hợp &ldquo;nhịp&rdquo; &ndash; kiểu gi&agrave;y mang cảm gi&aacute;c&nbsp;<strong>gọn, nhanh, d&iacute;nh ch&acirc;n</strong>.</p>\r\n<h2><span id=\"morelia-neo-4\">5. Morelia Neo 4: Kaizen &ndash; tinh chỉnh từng chi tiết, giữ chất K-Leather</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_ZkSc7Mzl.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack Neo 4\" width=\"1000\" height=\"522\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack Neo 4</figcaption>\r\n</figure>\r\n<p>Song h&agrave;nh với Alpha 3 l&agrave;&nbsp;<strong>Morelia Neo 4</strong>&nbsp;&ndash; đ&ocirc;i gi&agrave;y thể hiện r&otilde; triết l&yacute;&nbsp;<strong>KAIZEN</strong>&nbsp;của Mizuno: cải tiến li&ecirc;n tục, tốt hơn từng ch&uacute;t một, tinh chỉnh đến từng chi tiết nhỏ.</p>\r\n<p>Neo 4 tiếp tục giữ &ldquo;vũ kh&iacute;&rdquo; l&agrave;m n&ecirc;n t&ecirc;n tuổi: cảm gi&aacute;c chạm b&oacute;ng tự nhi&ecirc;n, &ocirc;m ch&acirc;n kiểu &ldquo;second-skin&rdquo; v&agrave; độ ho&agrave;n thiện rất Nhật. Mizuno kết hợp vật liệu hiện đại của thập kỷ mới c&ugrave;ng&nbsp;<strong>K-Leather trứ danh</strong>&nbsp;để tạo ra cảm gi&aacute;c mềm, thật ch&acirc;n nhưng vẫn theo kịp b&oacute;ng đ&aacute; hiện đại.</p>\r\n<p>Nếu bạn ưu ti&ecirc;n chạm b&oacute;ng, xoay trở trong kh&ocirc;ng gian hẹp, chuyền &ndash; nhận &ndash; giữ nhịp, v&agrave; th&iacute;ch một đ&ocirc;i gi&agrave;y mềm nhưng chắc, Neo 4 l&agrave; lựa chọn cực hợp để chơi tr&ecirc;n&nbsp;s&acirc;n cỏ nh&acirc;n tạo.</p>\r\n<h2><span id=\"goi-y-chon\">6. Gợi &yacute; chọn nhanh: bạn hợp Alpha hay Morelia Neo?</span></h2>\r\n<p>Chọn nhanh theo lối chơi để khỏi lăn tăn:</p>\r\n<ul>\r\n<li><strong>Chọn Alpha 3</strong>&nbsp;nếu bạn đ&aacute; thi&ecirc;n tốc độ, bứt tăng tốc nhiều, chạy c&aacute;nh &ndash; tiền đạo, th&iacute;ch cảm gi&aacute;c &ldquo;gọn &ndash; &ocirc;m &ndash; nhanh&rdquo;, ra s&acirc;n l&agrave; muốn chơi &ldquo;n&oacute;ng&rdquo; ngay.</li>\r\n<li><strong>Chọn Morelia Neo 4</strong>&nbsp;nếu bạn đặt cảm gi&aacute;c b&oacute;ng l&ecirc;n h&agrave;ng đầu, th&iacute;ch chạm thật, kiểm so&aacute;t b&oacute;ng chắc, form &ocirc;m mềm mại, v&agrave; m&ecirc; kiểu chất cổ điển nhưng vẫn rất hiệu quả.</li>\r\n</ul>\r\n<p>D&ugrave; bạn chọn silo n&agrave;o, Blazing Flair vẫn mang chung một th&ocirc;ng điệp:&nbsp;<strong>h&atilde;y embrace the heat</strong>&nbsp;&ndash; c&agrave;ng v&agrave;o trận c&agrave;ng gắt, c&agrave;ng b&ugrave;ng. Đ&acirc;y l&agrave; pack d&agrave;nh cho cầu thủ kh&ocirc;ng ngại thể hiện bản th&acirc;n, kh&ocirc;ng ngại đẩy giới hạn v&agrave; muốn để đ&ocirc;i gi&agrave;y n&oacute;i l&ecirc;n c&aacute; t&iacute;nh.</p>\r\n<p>Nếu bạn đang c&acirc;n nhắc đổi gi&agrave;y để ra s&acirc;n &ldquo;s&aacute;ng&rdquo; hơn, chơi tự tin hơn, Blazing Flair l&agrave; lựa chọn đ&aacute;ng thử b&ecirc;n cạnh c&aacute;c d&ograve;ng phổ biến từ&nbsp;adidas&nbsp;hay&nbsp;Nike. V&agrave; nếu vẫn ph&acirc;n v&acirc;n, cứ gh&eacute; cửa h&agrave;ng &ndash; thử l&ecirc;n ch&acirc;n sẽ ra đ&aacute;p &aacute;n nhanh nhất.</p>\r\n<h2><span id=\"he-thong-the-gioi-bong-da\">Hệ thống cửa h&agrave;ng Beyond</span></h2>\r\n<p>C&aacute;c nhận định v&agrave; trải nghiệm trong b&agrave;i được tổng hợp từ thực tế tư vấn, thử gi&agrave;y v&agrave; phản hồi của kh&aacute;ch h&agrave;ng tại hệ thống cửa h&agrave;ng Thế Giới B&oacute;ng Đ&aacute; &ndash; chuy&ecirc;n gi&agrave;y đ&aacute; b&oacute;ng ch&iacute;nh h&atilde;ng.</p>\r\n<p>Tại cửa h&agrave;ng, kh&aacute;ch h&agrave;ng c&oacute; thể thử trực tiếp từng d&ograve;ng gi&agrave;y theo form ch&acirc;n, được tư vấn size ph&ugrave; hợp v&agrave; hỗ trợ đổi size nếu chưa vừa khi sử dụng thực tế.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>\r\n</section>', '2025-09-03 14:24:40.865207', '', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1777606841/lk9ahsojumb6mw29wbmf.jpg', '', 0, 'Mizuno ‘Blazing Flair’ Pack – “Ignite The Pitch” và sắc hồng', 'mizuno-blazing-flair-pack-ignite-the-pitch-va-sac-hong', 'Mizuno ‘Blazing Flair’ Pack – “Ignite The Pitch” và sắc hồng', '2026-05-01 11:18:52.295881', NULL),
(12, '<h2><span id=\"concept\">1 Concept &ldquo;Ignite The Pitch&rdquo;: hiệu ứng bản đồ nhiệt v&agrave; tinh thần bứt ph&aacute;</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_KX47xSH9.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack 2\" width=\"1000\" height=\"725\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack</figcaption>\r\n</figure>\r\n<p>Điểm khiến Blazing Flair &ldquo;c&oacute; hồn&rdquo; kh&ocirc;ng chỉ nằm ở phối m&agrave;u, m&agrave; ở concept Mizuno x&acirc;y dựng cho cả pack: <strong>IGNITE THE PITCH</strong>. Hiểu đơn giản, đ&acirc;y l&agrave; c&acirc;u chuyện về&nbsp;<strong>nhiệt lượng</strong>&nbsp;&ndash; nhiệt của cơ thể, nhiệt của nhịp độ trận đấu, v&agrave; nhiệt của tham vọng khi bạn tăng tốc.</p>\r\n<p>Mizuno d&ugrave;ng cảm hứng&nbsp;<strong>infrared (hồng ngoại)</strong>&nbsp;để tạo cảm gi&aacute;c như một&nbsp;<strong>heat mapping</strong>&nbsp;(bản đồ nhiệt): mỗi bước chạy l&agrave; một lần &ldquo;đốt&rdquo; s&acirc;n, c&agrave;ng v&agrave;o trận c&agrave;ng n&oacute;ng, c&agrave;ng gắt, c&agrave;ng b&ugrave;ng. V&agrave; khi game l&ecirc;n cao tr&agrave;o, pack n&agrave;y nhắc bạn một điều:&nbsp;<strong>đừng n&eacute; nhiệt &ndash; h&atilde;y embrace the heat</strong>.</p>\r\n<p>Blazing Flair cũng l&agrave; một&nbsp;<strong>fiery statement</strong>&nbsp;d&agrave;nh cho những cầu thủ th&iacute;ch ph&aacute; giới hạn: d&aacute;m thể hiện, d&aacute;m kh&aacute;c biệt, d&aacute;m đ&aacute; theo c&aacute;ch của m&igrave;nh. M&agrave;u hồng &ndash; cam &ndash; t&iacute;m kh&ocirc;ng chỉ để nổi bật, m&agrave; để phản chiếu tinh thần&nbsp;<strong>fearless pursuit</strong>: theo đuổi sự tốt hơn một c&aacute;ch kh&ocirc;ng sợ h&atilde;i.</p>\r\n<h2><span id=\"mau-sac\">3. M&agrave;u sắc White/Pink Tetra/Fuchsia Purple: nổi bật nhưng kh&ocirc;ng &ldquo;lố&rdquo;</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_8j5fzCNn.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack 3\" width=\"1000\" height=\"725\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack</figcaption>\r\n</figure>\r\n<p>Blazing Flair xuất hiện trong bảng m&agrave;u&nbsp;<strong>White/Pink Tetra/Fuchsia Purple</strong>: nền trắng s&aacute;ng, phủ l&ecirc;n c&aacute;c mảng chuyển sắc hồng &ndash; t&iacute;m kiểu &ldquo;ch&aacute;y nhiệt&rdquo;. Nh&igrave;n ngo&agrave;i đời sẽ c&oacute; cảm gi&aacute;c&nbsp;<strong>ăn đ&egrave;n rất tốt</strong>, đặc biệt khi đ&aacute; s&acirc;n tối hoặc s&acirc;n c&oacute; đ&egrave;n mạnh.</p>\r\n<p>Điều hay l&agrave; Mizuno giữ được sự c&acirc;n bằng. D&ugrave; m&agrave;u nổi, tổng thể vẫn sạch v&agrave; dễ phối đồ s&acirc;n. Quan trọng hơn: mỗi silo &ldquo;dịch&rdquo; bảng m&agrave;u theo c&aacute;ch ri&ecirc;ng: Alpha 3 nh&igrave;n hiện đại, tốc độ; Morelia Neo 4 vẫn tối giản cổ điển nhưng được n&acirc;ng mood r&otilde; rệt.</p>\r\n<h2><span id=\"alpha-3\">4. Alpha 3: nhanh, &ocirc;m ch&acirc;n v&agrave; sinh ra cho những pha tăng tốc</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_9JzKdH9b.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack Alpha 3\" width=\"1000\" height=\"505\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack Alpha 3</figcaption>\r\n</figure>\r\n<p>T&acirc;m điểm của pack l&agrave;&nbsp;<strong>Alpha 3</strong>&nbsp;&ndash; d&ograve;ng &ldquo;fast&rdquo; của Mizuno với triết l&yacute; rất thẳng: đ&ocirc;i gi&agrave;y phải&nbsp;<strong>&ocirc;m ch&acirc;n như một phần cơ thể</strong>&nbsp;để bạn tăng tốc, đổi hướng tự nhi&ecirc;n v&agrave; gọn hơn.</p>\r\n<p>Điểm n&acirc;ng cấp đ&aacute;ng ch&uacute; &yacute; l&agrave;&nbsp;<strong>upper knit mới</strong>, được Mizuno ph&aacute;t triển để tạo cảm gi&aacute;c nhẹ, mềm v&agrave; &ldquo;adapt&rdquo; tốt khi ch&acirc;n hoạt động li&ecirc;n tục. Upper được gia cố bằng c&aacute;c đường kh&acirc;u ch&iacute;nh x&aacute;c, gi&uacute;p giữ form &ocirc;m v&agrave; hỗ trợ vừa đủ khi bạn bứt hoặc quặt gấp.</p>\r\n<p>Ở ph&iacute;a dưới, lớp đệm&nbsp;<strong>Mizuno Enerzy</strong>&nbsp;gi&uacute;p đ&ocirc;i gi&agrave;y c&oacute; độ &ecirc;m v&agrave; độ nảy dễ chịu hơn, đặc biệt hữu &iacute;ch với anh em đ&aacute; tốc độ cao nhưng vẫn muốn ch&acirc;n kh&ocirc;ng bị &ldquo;gắt&rdquo; sau 60&ndash;90 ph&uacute;t.</p>\r\n<p>Nếu bạn l&agrave; kiểu cầu thủ chạy c&aacute;nh, tiền đạo, hoặc đ&aacute; s&acirc;n 7 cần pressing v&agrave; di chuyển rộng, Alpha 3 l&agrave; lựa chọn rất hợp &ldquo;nhịp&rdquo; &ndash; kiểu gi&agrave;y mang cảm gi&aacute;c&nbsp;<strong>gọn, nhanh, d&iacute;nh ch&acirc;n</strong>.</p>\r\n<h2><span id=\"morelia-neo-4\">5. Morelia Neo 4: Kaizen &ndash; tinh chỉnh từng chi tiết, giữ chất K-Leather</span></h2>\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20260222_ZkSc7Mzl.jpg\" alt=\"Mizuno &lsquo;Blazing Flair&rsquo; Pack Neo 4\" width=\"1000\" height=\"522\" />\r\n<figcaption>Mizuno &lsquo;Blazing Flair&rsquo; Pack Neo 4</figcaption>\r\n</figure>\r\n<p>Song h&agrave;nh với Alpha 3 l&agrave;&nbsp;<strong>Morelia Neo 4</strong>&nbsp;&ndash; đ&ocirc;i gi&agrave;y thể hiện r&otilde; triết l&yacute;&nbsp;<strong>KAIZEN</strong>&nbsp;của Mizuno: cải tiến li&ecirc;n tục, tốt hơn từng ch&uacute;t một, tinh chỉnh đến từng chi tiết nhỏ.</p>\r\n<p>Neo 4 tiếp tục giữ &ldquo;vũ kh&iacute;&rdquo; l&agrave;m n&ecirc;n t&ecirc;n tuổi: cảm gi&aacute;c chạm b&oacute;ng tự nhi&ecirc;n, &ocirc;m ch&acirc;n kiểu &ldquo;second-skin&rdquo; v&agrave; độ ho&agrave;n thiện rất Nhật. Mizuno kết hợp vật liệu hiện đại của thập kỷ mới c&ugrave;ng&nbsp;<strong>K-Leather trứ danh</strong>&nbsp;để tạo ra cảm gi&aacute;c mềm, thật ch&acirc;n nhưng vẫn theo kịp b&oacute;ng đ&aacute; hiện đại.</p>\r\n<p>Nếu bạn ưu ti&ecirc;n chạm b&oacute;ng, xoay trở trong kh&ocirc;ng gian hẹp, chuyền &ndash; nhận &ndash; giữ nhịp, v&agrave; th&iacute;ch một đ&ocirc;i gi&agrave;y mềm nhưng chắc, Neo 4 l&agrave; lựa chọn cực hợp để chơi tr&ecirc;n&nbsp;<a href=\"https://thegioibongda.net/giay-da-bong-san-co-nhan-tao-pc200642.html\">s&acirc;n cỏ nh&acirc;n tạo</a>.</p>\r\n<h2><span id=\"goi-y-chon\">6. Gợi &yacute; chọn nhanh: bạn hợp Alpha hay Morelia Neo?</span></h2>\r\n<p>Chọn nhanh theo lối chơi để khỏi lăn tăn:</p>\r\n<ul>\r\n<li><strong>Chọn Alpha 3</strong>&nbsp;nếu bạn đ&aacute; thi&ecirc;n tốc độ, bứt tăng tốc nhiều, chạy c&aacute;nh &ndash; tiền đạo, th&iacute;ch cảm gi&aacute;c &ldquo;gọn &ndash; &ocirc;m &ndash; nhanh&rdquo;, ra s&acirc;n l&agrave; muốn chơi &ldquo;n&oacute;ng&rdquo; ngay.</li>\r\n<li><strong>Chọn Morelia Neo 4</strong>&nbsp;nếu bạn đặt cảm gi&aacute;c b&oacute;ng l&ecirc;n h&agrave;ng đầu, th&iacute;ch chạm thật, kiểm so&aacute;t b&oacute;ng chắc, form &ocirc;m mềm mại, v&agrave; m&ecirc; kiểu chất cổ điển nhưng vẫn rất hiệu quả.</li>\r\n</ul>\r\n<p>D&ugrave; bạn chọn silo n&agrave;o, Blazing Flair vẫn mang chung một th&ocirc;ng điệp:&nbsp;<strong>h&atilde;y embrace the heat</strong>&nbsp;&ndash; c&agrave;ng v&agrave;o trận c&agrave;ng gắt, c&agrave;ng b&ugrave;ng. Đ&acirc;y l&agrave; pack d&agrave;nh cho cầu thủ kh&ocirc;ng ngại thể hiện bản th&acirc;n, kh&ocirc;ng ngại đẩy giới hạn v&agrave; muốn để đ&ocirc;i gi&agrave;y n&oacute;i l&ecirc;n c&aacute; t&iacute;nh.</p>\r\n<p>Nếu bạn đang c&acirc;n nhắc đổi gi&agrave;y để ra s&acirc;n &ldquo;s&aacute;ng&rdquo; hơn, chơi tự tin hơn, Blazing Flair l&agrave; lựa chọn đ&aacute;ng thử b&ecirc;n cạnh c&aacute;c d&ograve;ng phổ biến từ&nbsp;<a href=\"https://thegioibongda.net/giay-da-bong-adidas-pc386022.html\">adidas</a>&nbsp;hay&nbsp;<a href=\"https://thegioibongda.net/giay-da-bong-nike-pc386013.html\">Nike</a>. V&agrave; nếu vẫn ph&acirc;n v&acirc;n, cứ gh&eacute; cửa h&agrave;ng &ndash; thử l&ecirc;n ch&acirc;n sẽ ra đ&aacute;p &aacute;n nhanh nhất.</p>', '2026-03-13 14:02:26.274014', 'Blazing Flair quy tụ hai dòng được quan tâm nhất hiện tại của Mizuno', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1773385315/lsjgazbpcxmmg9duke17.jpg', 'Blazing Flair quy tụ hai dòng được quan tâm nhất hiện tại của Mizuno', 0, 'Mizuno ‘Blazing Flair’ Pack – “Ignite The Pitch” và sắc hồng kiểu Nhật', 'mizuno-blazing-flair-pack-ignite-the-pitch-va-sac-hong-kieu-nhat', 'Mizuno ‘Blazing Flair’ Pack – “Ignite The Pitch” và sắc hồng kiểu Nhật', '2026-03-13 14:02:26.280862', NULL);
INSERT INTO `blog` (`id`, `content`, `created_date`, `description`, `image_banner`, `meta_description`, `num_view`, `seo_title`, `slug`, `title`, `update_date`, `user_id`) VALUES
(13, '<blockquote><header class=\"entry-header\">\r\n<div class=\"entry-header-text entry-header-text-top text-left\">\r\n<h1 class=\"entry-title\">Quy tr&igrave;nh sản xuất gi&agrave;y đ&aacute; b&oacute;ng tại Wika như thế n&agrave;o?</h1>\r\n</div>\r\n</header>\r\n<div class=\"entry-content single-page\">\r\n<p>Sản xuất giầy đ&aacute; b&oacute;ng th&igrave; c&oacute; mấy c&ocirc;ng đoạn? Chắc hẳn c&aacute;c bạn lu&ocirc;n thắc mắc quy tr&igrave;nh sản xuất gi&agrave;y tại Wika như thế n&agrave;o? B&agrave;i viết h&ocirc;m nay ch&uacute;ng t&ocirc;i xin giới thiệu tới c&aacute;c bạn quy tr&igrave;nh sản xuất gi&agrave;y v&agrave; c&aacute;c c&ocirc;ng nghệ ti&ecirc;n tiến nhất được sử dụng với đ&ocirc;i gi&agrave;y mang thương hiệu Wika.</p>\r\n</div>\r\n</blockquote>\r\n<blockquote>\r\n<div class=\"entry-content single-page\">\r\n<div id=\"ez-toc-container\" class=\"ez-toc-v2_0_63 counter-hierarchy ez-toc-counter ez-toc-grey ez-toc-container-direction\">\r\n<div class=\"ez-toc-title-container\">\r\n<p class=\"ez-toc-title \">Nội Dung</p>\r\n</div>\r\n<nav>\r\n<ul class=\"ez-toc-list ez-toc-list-level-1 \">\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-2\">Quy tr&igrave;nh sản xuất giầy đ&aacute; b&oacute;ng tại Wika\r\n<ul class=\"ez-toc-list-level-3\">\r\n<li class=\"ez-toc-heading-level-3\">Bước 1: Thiết kế v&agrave; sản xuất gi&agrave;y da</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-3\">Bước 2: May v&agrave; sản xuất đế gi&agrave;y</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-3\">Bước 3: Lắp gi&aacute;p v&agrave; ho&agrave;n thiện</li>\r\n</ul>\r\n</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-2\">C&ocirc;ng nghệ sản xuất giầy đ&aacute; b&oacute;ng\r\n<ul class=\"ez-toc-list-level-3\">\r\n<li class=\"ez-toc-heading-level-3\">C&ocirc;ng nghệ E.V.A Carbon</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-3\">C&ocirc;ng nghệ đế gi&agrave;y 2 lớp</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-3\">C&ocirc;ng nghệ Microfiber</li>\r\n</ul>\r\n</li>\r\n<li class=\"ez-toc-page-1 ez-toc-heading-level-2\">Tiềm lực t&agrave;i ch&iacute;nh &amp; khả năng sản xuất</li>\r\n</ul>\r\n</nav></div>\r\n<h2>Quy tr&igrave;nh sản xuất giầy đ&aacute; b&oacute;ng tại Wika</h2>\r\n<h3>Bước 1: Thiết kế v&agrave; sản xuất gi&agrave;y da</h3>\r\n<p>C&aacute;c miếng da l&agrave;m gi&agrave;y sẽ được cắt ra v&agrave; đ&aacute;nh dấu trong qu&aacute; tr&igrave;nh dập để tr&aacute;nh nhầm lẫn. Một khi c&aacute;c miếng da đ&atilde; được đ&oacute;ng dấu, c&aacute;c điểm tr&ecirc;n mỗi miếng da sau đ&oacute; sẽ được gắn với những miếng da kh&aacute;c cũng được đ&aacute;nh dấu tương tự. Để bước n&agrave;y c&oacute; thể thực hiện dễ d&agrave;ng th&igrave; c&aacute;c cạnh của mỗi mảnh da phải mỏng. C&aacute;c địa điểm cần đục lỗ cũng được đ&aacute;nh dấu. Nếu muốn gi&agrave;y c&oacute; họa tiết đục lỗ trang tr&iacute; phải đ&aacute;nh dấu v&agrave; đục lỗ tr&ecirc;n da trước.</p>\r\n<figure id=\"attachment_322\" class=\"wp-caption aligncenter\" style=\"text-align: center;\" aria-describedby=\"caption-attachment-322\"><img class=\"wp-image-322 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-3_optimized\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-3_optimized.jpg\" data-ll-status=\"loaded\" />\r\n<figcaption id=\"caption-attachment-322\" class=\"wp-caption-text\">D&acirc;y chuyền kh&eacute;p k&iacute;n tại xưởng may của Wika</figcaption>\r\n</figure>\r\n<p><strong>Thiết kế v&agrave; t&aacute;ch chi tiết gi&agrave;y</strong>: đ&acirc;y l&agrave; c&ocirc;ng đoạn quan trọng của sản xu&acirc;t gi&agrave;y da. C&aacute;c c&ocirc;ng đoạn sau cũng đều phụ thuộc v&agrave;o qu&aacute; tr&igrave;nh n&agrave;y.</p>\r\n<p><strong>Cắt chi tiết</strong>: &Aacute;p những bản vẽ chi tiết l&ecirc;n bề mặt da thuộc v&agrave; phải cắt tỉa sao cho đ&uacute;ng k&iacute;ch cỡ c&oacute; sẵn. C&ocirc;ng đoạn n&agrave;y đ&ograve;i hỏi một c&aacute;ch tỷ mỉ để đảm bảo độ ch&iacute;nh x&aacute;c về số đo v&agrave; nhằm tiết kiệm da thuộc nhưng vẫn đảm bảo chất lượng k&iacute;ch thước của kiểu d&aacute;ng gi&agrave;y.</p>\r\n<p><strong>D&atilde;y chi tiết</strong>: gh&eacute;p c&aacute;c chi tiết v&agrave;o với nhau sao cho hợp l&yacute; nhất đảm bảo t&iacute;nh thẩm mỹ của gi&agrave;y.</p>\r\n<h3>Bước 2: May v&agrave; sản xuất đế gi&agrave;y</h3>\r\n<p><strong>May c&aacute;c chi tiết</strong>: c&aacute;c chi tiết được may t&aacute;ch biệt nhau sao cho ph&ugrave; hợp với kiểu d&aacute;ng của gi&agrave;y.</p>\r\n<center>\r\n<div class=\"rll-youtube-player\" data-src=\"https://www.youtube.com/embed/8xXXvagaEb0\" data-id=\"8xXXvagaEb0\" data-query=\"\" data-alt=\"YouTube video player\">\r\n<div data-id=\"8xXXvagaEb0\" data-query=\"\" data-src=\"https://www.youtube.com/embed/8xXXvagaEb0\"><img class=\"entered lazyloaded\" src=\"https://i.ytimg.com/vi/8xXXvagaEb0/hqdefault.jpg\" alt=\"YouTube video player\" width=\"480\" height=\"360\" data-lazy-src=\"https://i.ytimg.com/vi/8xXXvagaEb0/hqdefault.jpg\" data-ll-status=\"loaded\" /></div>\r\n</div>\r\n</center><center>May c&aacute;c chi tiết</center>\r\n<p><strong>Ho&agrave;n thiện chi tiết</strong>: C&aacute;c chi tiết sau khi đ&atilde; được thiết kế, cắt, gấp, may. Ch&iacute;nh l&agrave; gh&eacute;p c&aacute;c chi tiết theo bản thiết kế đ&atilde; c&oacute; sẵn.</p>\r\n<figure id=\"attachment_323\" class=\"wp-caption aligncenter\" aria-describedby=\"caption-attachment-323\"><img class=\"wp-image-323 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-4\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-4_optimized.jpg\" data-ll-status=\"loaded\" />\r\n<figcaption id=\"caption-attachment-323\" class=\"wp-caption-text\">Đế gi&agrave;y cao su non</figcaption>\r\n</figure>\r\n<p>Trong giai đoạn may, c&aacute;c miếng da đ&atilde; được cắt sẵn ra sẽ được kh&acirc;u với nhau. Đầu ti&ecirc;n, c&aacute;c miếng gh&eacute;p phần tr&ecirc;n sẽ được kh&acirc;u lại, sau đ&oacute; l&agrave; lớp l&oacute;t. Gi&agrave;y được gia cố th&ecirc;m ở phần ng&oacute;n ch&acirc;n v&agrave; đệm l&oacute;t gi&agrave;y. Để tr&aacute;nh việc những mảnh da bị trượt đi, ban đầu ch&uacute;ng được chấm keo l&ecirc;n c&aacute;c cạnh v&agrave; gắn lại với nhau. Phần tr&ecirc;n gi&agrave;y sẽ được kh&acirc;u lại trước, sau đ&oacute; l&agrave; phần l&oacute;t. Sau khi đ&atilde; kh&acirc;u hai phần n&agrave;y, c&aacute;c đường may cũng được l&agrave;m gọn. Đế gi&agrave;y phải trải qua c&ocirc;ng đoạn g&ograve; trước khi đem đi gi&aacute;p v&agrave;o phần mũ gi&agrave;y, thường được l&agrave;m bằng m&aacute;y.</p>\r\n<h3>Bước 3: Lắp gi&aacute;p v&agrave; ho&agrave;n thiện</h3>\r\n<p>Sau khi đế gi&agrave;y đ&atilde; được g&ograve; xong th&igrave; sẽ tiến h&agrave;nh đến phần gi&aacute;p đế. Qu&eacute;t keo l&ecirc;n mặt sau để d&aacute;n v&agrave;o cốt gi&agrave;y. Phần mũ gi&agrave;y v&agrave; phần đế gi&agrave;y sẽ được gi&aacute;p lại với nhau bằng c&aacute;c m&aacute;y chuy&ecirc;n dụng.</p>\r\n<figure id=\"attachment_318\" class=\"wp-caption aligncenter\" aria-describedby=\"caption-attachment-318\"><img class=\"wp-image-318 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-1_optimized\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-1_optimized.jpg\" data-ll-status=\"loaded\" />\r\n<figcaption id=\"caption-attachment-318\" class=\"wp-caption-text\">Bộ phận ho&agrave;n thiện sản phẩm</figcaption>\r\n</figure>\r\n<p>Ở mỗi kh&acirc;u kh&aacute;c nhau đều c&oacute; những người thơ đảm nhận nhiệm vụ ri&ecirc;ng của m&igrave;nh. Cuối c&ugrave;ng, bộ phận ho&agrave;n thiện sẽ thực hiện những c&ocirc;ng đoạn cuối như: luồn d&acirc;y gi&agrave;y, kiểm tra đường may, đ&aacute;nh b&oacute;ng .. Th&agrave;nh phẩm sẽ được đ&oacute;ng hộp v&agrave; gửi đến c&aacute;c nh&agrave; ph&acirc;n phối, đại l&yacute;.</p>\r\n<figure id=\"attachment_324\" class=\"wp-caption aligncenter\" aria-describedby=\"caption-attachment-324\"><img class=\"wp-image-324 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-5\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-5_optimized.jpg\" data-ll-status=\"loaded\" />\r\n<figcaption id=\"caption-attachment-324\" class=\"wp-caption-text\">Th&agrave;nh phẩm được đ&oacute;ng g&oacute;i full box</figcaption>\r\n</figure>\r\n<h2>C&ocirc;ng nghệ sản xuất giầy đ&aacute; b&oacute;ng</h2>\r\n<p><img class=\"aligncenter wp-image-327 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-8\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-8_optimized.jpg\" data-ll-status=\"loaded\" /></p>\r\n<h3>C&ocirc;ng nghệ E.V.A Carbon</h3>\r\n<p>Wika sử dụng c&ocirc;ng nghệ l&oacute;t gi&agrave;y E.V.A Carbon kết hợp với c&aacute;c hạt nhựa đặc biệt gi&uacute;p hấp thụ chấn động cực tốt v&agrave; đ&agrave;n hồi giảm chấn thương, chống trượt, &ecirc;m ch&acirc;n v&agrave; đặc biệt tho&aacute;ng kh&iacute; gi&uacute;p hạn chế mồ h&ocirc;i ch&acirc;n khi chơi thể thao.<img class=\"aligncenter wp-image-328 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-9\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-9_optimized.jpg\" data-ll-status=\"loaded\" /></p>\r\n<h3>C&ocirc;ng nghệ đế gi&agrave;y 2 lớp</h3>\r\n<p><img class=\"aligncenter wp-image-325 size-full entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-10\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-10_optimized.jpg\" data-ll-status=\"loaded\" /></p>\r\n<p>Đế gi&agrave;y cao su 2 lớp được Wika thiết kế lần đầu ti&ecirc;n tại Việt Nam gi&uacute;p việc di chuyển tr&ecirc;n s&acirc;n linh hoạt, mềm mại hơn. Form gi&agrave;y chuẩn Việt cực &ocirc;m ch&acirc;n hỗ trợ khả năng tăng tốc, xoay sở trong phạm vi hẹp, giảm chấn thương.</p>\r\n<h3>C&ocirc;ng nghệ Microfiber</h3>\r\n<p>Mũi gi&agrave;y sử dụng c&ocirc;ng nghệ da Microfiber, l&agrave; chất liệu cao cấp nhất tr&ecirc;n thị trường gi&agrave;y đ&aacute; b&oacute;ng hiện nay (vượt xa so với chất liệu PU loại 1,2,3,4). Microfiber thực chất l&agrave; một loại sợi c&oacute; cấu tr&uacute;c rất nhỏ, chỉ bằng 1/5 đường k&iacute;nh sợi t&oacute;c của ch&uacute;ng ta, được tạo ra từ 2 chất Polyester v&agrave; Polyamide n&ecirc;n đ&atilde; thừa hưởng được những ưu điểm của 2 loại sợi n&agrave;y.</p>\r\n<p><img class=\"wp-image-326 size-full aligncenter entered lazyloaded\" src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized.jpg\" sizes=\"(max-width: 1280px) 100vw, 1280px\" srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-768x432.jpg 768w\" alt=\"quy-trinh-san-xuat-giay-da-bong-wika-7\" width=\"1280\" height=\"720\" data-lazy-srcset=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized.jpg 1280w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-600x338.jpg 600w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-300x169.jpg 300w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-1024x576.jpg 1024w, https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized-768x432.jpg 768w\" data-lazy-sizes=\"(max-width: 1280px) 100vw, 1280px\" data-lazy-src=\"https://wikasports.com/wp-content/uploads/2021/06/quy-trinh-san-xuat-giay-da-bong-wika-7_optimized.jpg\" data-ll-status=\"loaded\" /></p>\r\n<p>Nếu như Polyester mang lại độ bền v&agrave; độ cứng cần thiết th&igrave; sợi Polyamide cung cấp khả năng hấp thụ chấn động cho chất liệu n&agrave;y. Sợi Microfiber thể hiện m&igrave;nh c&oacute; rất nhiều c&aacute;c t&iacute;nh năng từ sự mềm dẻo, hấp thụ đến khả năng chống thấm nước, tĩnh điện v&agrave; lọc khuẩn v&agrave; l&agrave; chất liệu l&yacute; tưởng để tạo ra một đ&ocirc;i gi&agrave;y ho&agrave;n hảo gi&uacute;p bạn thể hiện được tối đa kỹ năng tr&ecirc;n s&acirc;n cỏ.</p>\r\n<h2>Tiềm lực t&agrave;i ch&iacute;nh &amp; khả năng sản xuất</h2>\r\n<p><strong>Wika</strong>&nbsp;l&agrave; một thương hiệu của Cty TNHH TM &amp; SX Thể Thao Ho&agrave;ng Phong, một trong những doanh nghiệp đứng đầu ng&agrave;nh c&ocirc;ng nghiệp gi&agrave;y tại Việt Nam.</p>\r\n<p>Với số vốn đầu tư ban đầu l&agrave; 500.000 USD cho đến nay tổng số vốn doanh nghiệp hiện c&oacute; đạt 20 triệu USD v&agrave; gần 20 năm kinh nghiệm.&nbsp;</p>\r\n<p><strong>Wika</strong>&nbsp;c&oacute; nh&agrave; m&aacute;y sản xuất tại Việt Nam với tầm nh&igrave;n, năng lực ti&ecirc;u chuẩn quốc tế v&agrave; chiến lược kinh doanh lu&ocirc;n lấy lợi &iacute;ch kh&aacute;ch h&agrave;ng l&agrave;m ưu ti&ecirc;n h&agrave;ng đầu. Năng lực sản xuất quy m&ocirc; lớn: sở hữu d&acirc;y chuyền sản xuất kh&eacute;p k&iacute;n, chuy&ecirc;n nghiệp, c&ocirc;ng nghệ cao. Nguồn nh&acirc;n lực dồi d&agrave;o, đam m&ecirc;, đo&agrave;n kết v&agrave; s&aacute;ng tạo với 10.000 c&aacute;n bộ, c&ocirc;ng nh&acirc;n vi&ecirc;n v&agrave; 8 ph&acirc;n xưởng, 20 d&acirc;y chuyền sản xuất với năng lực hiện tại 10.000 đ&ocirc;i gi&agrave;y/ ng&agrave;y.</p>\r\n<p>Tr&ecirc;n đ&acirc;y, c&aacute;c bạn đ&atilde; kh&aacute;m ph&aacute; ra 3 c&ocirc;ng đoạn để sản xuất ra 1 chiếc&nbsp;<strong>giầy đ&aacute; b&oacute;ng</strong>&nbsp;ho&agrave;n chỉnh, th&ecirc;m v&agrave;o đ&oacute; l&agrave; c&aacute;c c&ocirc;ng nghệ hiện đại m&agrave; Wika đ&atilde; sử dụng. Nếu thấy hay h&atilde;y chia sẻ v&agrave; ủng hộ&nbsp;sản phẩm gi&agrave;y đ&aacute; b&oacute;ng&nbsp;tại Wika nha!</p>\r\n</div>\r\n</blockquote>', '2025-09-01 21:03:19.096135', '', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1777608359/es5ozvjvjxlmut8sgy39.jpg', '', 0, 'Quy trình sản xuất giày đá bóng tại Wika như thế nào?', 'quy-trinh-san-xuat-giay-a-bong-tai-wika-nhu-the-nao', 'Quy trình sản xuất giày đá bóng tại Wika như thế nào?', '2026-05-01 11:20:41.986054', NULL),
(14, '<section class=\"right-content col-lg-9 col-12 mx-auto\">\r\n<article class=\"article-main\">\r\n<div class=\"article-details\">\r\n<div class=\"article-content js-toc-content\">\r\n<div id=\"ega-uti-editable-content\" class=\"rte\" data-platform=\"haravan\" data-id=\"1002742863\" data-blog-id=\"1000950832\">\r\n<blockquote>\r\n<h1 style=\"text-align: center;\">GI&Agrave;Y Đ&Aacute; B&Oacute;NG JOMA TOP FLEX: CHỌN SAO CHO Đ&Uacute;NG?</h1>\r\n<div class=\"art-body\">\r\n<div class=\"art-summary\">&nbsp;</div>\r\n<div class=\"art-date\">12/04/2026</div>\r\n<div class=\"art-text\">\r\n<p>Trong Futsal, c&aacute;i t&ecirc;n&nbsp;Joma Top Flex từ l&acirc;u đ&atilde; trở th&agrave;nh biểu tượng của sự bền bỉ v&agrave; thoải m&aacute;i. Tuy nhi&ecirc;n, với sự đa dạng của c&aacute;c phi&ecirc;n bản hiện nay, kh&ocirc;ng &iacute;t anh em cảm thấy ph&acirc;n v&acirc;n khi lựa chọn.</p>\r\n<p>Trước khi quyết định \"xuống tiền\" cho c&aacute;c mẫu gi&agrave;y s&acirc;n s&agrave;n Joma y&ecirc;u th&iacute;ch, h&atilde;y c&ugrave;ng Beyond điểm qua 3 lưu &yacute; mấu chốt dưới đ&acirc;y để chọn được đ&ocirc;i gi&agrave;y đ&aacute; b&oacute;ng chuẩn nhất cho đ&ocirc;i ch&acirc;n của m&igrave;nh.</p>\r\n<h3><strong>1. Ph&acirc;n cấp c&aacute;c phi&ecirc;n bản của gi&agrave;y đ&aacute; b&oacute;ng&nbsp;Joma Top Flex</strong></h3>\r\n<p>Thương hiệu đến từ T&acirc;y Ban Nha đ&atilde; rất t&acirc;m l&yacute; khi chia d&ograve;ng gi&agrave;y Futsal Joma Top Flex th&agrave;nh nhiều ph&acirc;n kh&uacute;c dựa tr&ecirc;n phần đệm l&oacute;t:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Joma Top Flex (Bản thường)</strong>: Đ&acirc;y l&agrave; phi&ecirc;n bản cơ bản v&agrave; kinh điển nhất. Gi&agrave;y sở hữu upper từ da heo hoặc da nh&acirc;n tạo, đi c&ugrave;ng bộ đệm EVA truyền thống mang lại sự linh hoạt tối đa.</p>\r\n</li>\r\n<li>\r\n<p><strong>Joma Top Flex Rebound</strong>: Giữ nguy&ecirc;n c&aacute;c ưu điểm về phom d&aacute;ng của bản thường nhưng được n&acirc;ng cấp bộ đệm Rebound. Điều n&agrave;y mang lại cảm gi&aacute;c &ecirc;m &aacute;i v&agrave; độ đ&agrave;n hồi tốt hơn hẳn trong từng bước chạy.</p>\r\n</li>\r\n<li>\r\n<p><strong>Joma Top Flex Plus</strong>: Tiếp tục đẩy mạnh khả năng giảm chấn với bộ đệm d&agrave;y dặn, gi&uacute;p bảo vệ khớp gối tuyệt vời cho những anh em c&oacute; cường độ thi đấu cao.</p>\r\n</li>\r\n<li>\r\n<p><strong>Joma Top Flex Ultimate</strong>: Đ&acirc;y l&agrave; phi&ecirc;n bản cao cấp nhất hiện tại. Mẫu gi&agrave;y Futsal Joma n&agrave;y hội tụ đầy đủ những c&ocirc;ng nghệ t&acirc;n tiến nhất, mang đến hiệu năng thi đấu đỉnh cao.</p>\r\n</li>\r\n</ul>\r\n<div>\r\n<p><img class=\"dt-width-auto\" src=\"https://cdn.hstatic.net/200000278317/file/ong-joma-top-flex-chon-sao-cho-dung-1_c09b8aa7a4774cc08638c487cf13f01f.jpg\" alt=\"GI&Agrave;Y Đ&Aacute; B&Oacute;NG JOMA TOP FLEX: CHỌN SAO CHO Đ&Uacute;NG?\" width=\"600\" height=\"600\" /></p>\r\n</div>\r\n<h3><strong>2. Độ cao đế gi&agrave;y - Yếu tố quyết định cảm gi&aacute;c b&oacute;ng</strong></h3>\r\n<p>Độ cao đế l&agrave; điểm cực kỳ quan trọng, ảnh hưởng trực tiếp đến cảm gi&aacute;c chạm b&oacute;ng v&agrave; khả năng xoay trở của anh em tr&ecirc;n mặt s&acirc;n s&agrave;n.</p>\r\n<ul>\r\n<li>\r\n<p>Thứ tự độ cao từ thấp đến cao:&nbsp;<strong>Bản Thường &lt; Ultimate &lt; Rebound &lt; Plu</strong>s (cao nhất).</p>\r\n</li>\r\n<li>\r\n<p>Lựa chọn theo lối chơi: Nếu anh em th&iacute;ch cảm gi&aacute;c đế mỏng, dễ v&ecirc; gầm v&agrave; trọng t&acirc;m thấp để tiếp x&uacute;c gần mặt s&acirc;n, th&igrave; gi&agrave;y đ&aacute; b&oacute;ng Futsal Joma Top Flex bản thường v&agrave; Ultimate ch&iacute;nh l&agrave; \"ch&acirc;n &aacute;i\".</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ khớp gối: Ngược lại, nếu anh em cần một bộ đệm d&agrave;y để hỗ trợ giảm chấn cho khớp gối trong c&aacute;c pha bứt tốc hay đặt trụ xoay trở, th&igrave; Rebound v&agrave; Plus sẽ l&agrave; lựa chọn tối ưu nhất.</p>\r\n</li>\r\n</ul>\r\n<div>\r\n<p><img class=\"dt-width-auto\" src=\"https://cdn.hstatic.net/200000278317/file/ong-joma-top-flex-chon-sao-cho-dung-2_a52bcd5c712e4249a283ac64c5efb768.jpg\" alt=\"GI&Agrave;Y Đ&Aacute; B&Oacute;NG JOMA TOP FLEX: CHỌN SAO CHO Đ&Uacute;NG?\" width=\"600\" height=\"600\" /></p>\r\n</div>\r\n<h3><strong>3. Form d&aacute;ng v&agrave; độ &ocirc;m ch&acirc;n thực tế</strong></h3>\r\n<p>D&ugrave; cả 4 phi&ecirc;n bản đều được mệnh danh l&agrave; \"cứu tinh\" cho anh em ch&acirc;n b&egrave;, nhưng cảm gi&aacute;c thực tế của d&ograve;ng gi&agrave;y Futsal Joma Top Flex vẫn c&oacute; sự kh&aacute;c biệt nhỏ:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Bản Thường, Rebound v&agrave; Plus</strong>: Ba phi&ecirc;n bản n&agrave;y c&oacute; phom d&aacute;ng kh&aacute; tương đồng, mang lại cảm gi&aacute;c cực kỳ thoải m&aacute;i v&agrave; tho&aacute;ng ch&acirc;n, đặc biệt ph&ugrave; hợp cho những ai c&oacute; b&agrave;n ch&acirc;n to ngang đặc trưng của người Việt.</p>\r\n</li>\r\n<li>\r\n<p><strong>Bản Ultimate</strong>: D&ugrave; vẫn d&agrave;nh cho ch&acirc;n b&egrave; nhưng thiết kế của Ultimate c&oacute; phần thon gọn v&agrave; hiện đại hơn. N&oacute; mang lại độ &ocirc;m ch&acirc;n kh&iacute;t hơn một ch&uacute;t so với 3 phi&ecirc;n bản c&ograve;n lại, ph&ugrave; hợp cho anh em th&iacute;ch sự gọn g&agrave;ng nhưng vẫn kh&ocirc;ng bị b&oacute; tức.</p>\r\n</li>\r\n</ul>\r\n<div>\r\n<p><img class=\"dt-width-auto\" src=\"https://cdn.hstatic.net/200000278317/file/ong-joma-top-flex-chon-sao-cho-dung-3_10dec36ae86c4807a4be72ceb647b908.jpg\" alt=\"GI&Agrave;Y Đ&Aacute; B&Oacute;NG JOMA TOP FLEX: CHỌN SAO CHO Đ&Uacute;NG?\" width=\"600\" height=\"600\" /></p>\r\n</div>\r\n<h3><strong>KẾT LUẬN</strong></h3>\r\n<p>D&ograve;ng gi&agrave;y Futsal&nbsp;Joma n&oacute;i chung v&agrave; c&aacute;c silo Top Flex n&oacute;i ri&ecirc;ng vẫn lu&ocirc;n l&agrave; lựa chọn h&agrave;ng đầu nhờ sự đa dạng v&agrave; chất lượng vượt trội. Hy vọng b&agrave;i viết n&agrave;y đ&atilde; gi&uacute;p anh em hiểu r&otilde; hơn về c&aacute;c ph&acirc;n kh&uacute;c của gi&agrave;y đ&aacute; b&oacute;ng Futsal Joma Top Flex để tự tin chốt đơn đ&ocirc;i gi&agrave;y ph&ugrave; hợp nhất.</p>\r\n<p>Gh&eacute; ngay Beyond để trải nghiệm thực tế v&agrave; nhận tư vấn chi tiết nhất nh&eacute;!</p>\r\n<p>Được ra đời từ năm 2013,&nbsp;Beyond&nbsp;tự h&agrave;o l&agrave; một trong những nh&agrave; b&aacute;n lẻ h&agrave;ng đầu trong mảng sản phẩm gi&agrave;y đ&aacute; b&oacute;ng ch&iacute;nh h&atilde;ng tại Việt Nam.&nbsp;</p>\r\n<p>Đội ngũ Beyond đ&atilde; v&agrave; đang nỗ lực nhằm đem lại cho kh&aacute;ch h&agrave;ng những trải nghiệm tốt nhất về chất lượng sản phẩm v&agrave; dịch vụ, cũng như đưa ra những tư vấn tận t&acirc;m để kh&aacute;ch h&agrave;ng c&oacute; thể chọn lựa được cho m&igrave;nh những đ&ocirc;i gi&agrave;y đ&aacute; banh ph&ugrave; hợp nhất, ưng &yacute; nhất mỗi khi ra s&acirc;n.</p>\r\n<p>Đối với mỗi đ&ocirc;i&nbsp;gi&agrave;y đ&aacute; b&oacute;ng&nbsp;mua tại Beyond, anh em sẽ được tặng 1 balo mini đựng gi&agrave;y, 1 đ&ocirc;i tất đ&aacute; b&oacute;ng hoặc 1 &aacute;o mưa mang nh&atilde;n hiệu THF.</p>\r\n<p>Ngo&agrave;i ra, Beyond c&ograve;n hỗ trợ trả g&oacute;p tại cửa h&agrave;ng hoặc online th&ocirc;ng qua Fundiin.</p>\r\n<p>Đối với c&aacute;c đơn gi&agrave;y đ&aacute; banh đặt mua online, Beyond hỗ trợ giao h&agrave;ng tận nơi v&agrave; freeship to&agrave;n quốc.</p>\r\n</div>\r\n</div>\r\n</blockquote>\r\n</div>\r\n</div>\r\n</div>\r\n</article>\r\n</section>', '2025-09-03 14:15:40.685581', '', 'http://res.cloudinary.com/dt2g4oabz/image/upload/v1777608024/o0njgls0oypukek3asai.jpg', '', 0, 'GIÀY ĐÁ BÓNG JOMA TOP FLEX: CHỌN SAO CHO ĐÚNG?', 'giay-a-bong-joma-top-flex-chon-sao-cho-ung', 'GIÀY ĐÁ BÓNG JOMA TOP FLEX: CHỌN SAO CHO ĐÚNG?', '2026-05-01 11:20:16.359025', NULL);
INSERT INTO `blog` (`id`, `content`, `created_date`, `description`, `image_banner`, `meta_description`, `num_view`, `seo_title`, `slug`, `title`, `update_date`, `user_id`) VALUES
(15, '<h1 style=\"text-align: center;\">Nike Air Zoom Mercurial Cosmic Speed : Sự trở lại đầy b&ugrave;ng nổ</h1>\r\n<div class=\"title-main-home\">\r\n<figure class=\"image\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20241120_iWwnRQ4Y.jpg\" alt=\"20241120_iWwnRQ4Y.jpg\" width=\"1000\" height=\"573\" /></figure>\r\n<p>Sau khi d&ograve;ng&nbsp;<strong>Dream Speed</strong>&nbsp;kh&eacute;p lại h&agrave;nh tr&igrave;nh lừng lẫy từ năm 2019, Nike kh&ocirc;ng để người h&acirc;m mộ phải chờ l&acirc;u khi ngay lập tức cho ra mắt bộ sưu tập mới đầy t&aacute;o bạo mang t&ecirc;n<strong>&nbsp;Mercurial Cosmic Speed</strong>. Được ra mắt v&agrave;o th&aacute;ng 9 năm nay,&nbsp;<strong>Nike Air Zoom Cosmic Speed</strong>&nbsp;nhanh ch&oacute;ng trở th&agrave;nh biểu tượng mới, kế thừa v&agrave; ph&aacute;t triển những gi&aacute; trị tinh hoa của d&ograve;ng&nbsp;<strong>Mercurial</strong>&nbsp;huyền thoại, đặc biệt l&agrave; kế thừa MDS để trở th&agrave;nh một trong những biểu tượng kinh điển của d&ograve;ng gi&agrave;y b&oacute;ng đ&aacute; tốc độ.</p>\r\n<p>Thế hệ thứ hai của&nbsp;<strong>Cosmic Speed</strong>&nbsp;đ&atilde; ch&iacute;nh thức tr&igrave;nh l&agrave;ng với hai phối m&agrave;u độc đ&aacute;o d&agrave;nh cho&nbsp;<strong>Air Zoom Mercurial Vapor 16</strong><strong>&nbsp;</strong>v&agrave;&nbsp;<strong>Superfly 10</strong>, hứa hẹn sẽ khuấy đảo s&acirc;n cỏ to&agrave;n cầu với thiết kế đột ph&aacute; v&agrave; c&ocirc;ng nghệ ti&ecirc;n tiến.</p>\r\n<h2>Sự chuyển giao từ&nbsp;<strong>Dream Speed</strong>&nbsp;sang&nbsp;<strong>Cosmic Speed</strong></h2>\r\n<p style=\"text-align: center;\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20241120_FiA01wu5.jpg\" alt=\"Dream Speed sang Cosmic Speed 1\" width=\"1000\" height=\"573\" /></p>\r\n<p style=\"text-align: center;\"><img src=\"https://pos.nvncdn.com/3c8244-211061/art/artCT/20241120_Ao7muYvI.jpg\" alt=\"Dream Speed sang Cosmic Speed 2\" width=\"1000\" height=\"573\" /></p>\r\n<p>D&ograve;ng&nbsp;<strong>Dream Speed</strong>&nbsp;từng l&agrave; biểu tượng đặc biệt d&agrave;nh cho Nike Mercurial từ năm 2019, với mỗi phi&ecirc;n bản đều mang đến thiết kế ri&ecirc;ng biệt, nổi bật v&agrave; đậm chất s&aacute;ng tạo. Từ đ&ocirc;i Dream Speed 001 đầu ti&ecirc;n đến phi&ecirc;n bản Dream Speed 009 kh&eacute;p lại chu kỳ v&agrave;o th&aacute;ng 11 năm nay, d&ograve;ng sản phẩm n&agrave;y lu&ocirc;n đồng h&agrave;nh c&ugrave;ng những ng&ocirc;i sao tốc độ h&agrave;ng đầu thế giới như&nbsp;<strong>Cristiano Ronaldo</strong>&nbsp;hay&nbsp;<strong>Kylian Mbappe</strong>.</p>\r\n<p>Tuy nhi&ecirc;n, sự ra đời của Cosmic Speed kh&ocirc;ng chỉ l&agrave; một bước chuyển m&igrave;nh m&agrave; c&ograve;n l&agrave; minh chứng cho khả năng s&aacute;ng tạo kh&ocirc;ng ngừng của Nike. Phi&ecirc;n bản đầu ti&ecirc;n của bộ sưu tập Cosmic Speed đ&atilde; g&acirc;y ch&uacute; &yacute; với phong c&aacute;ch tối giản, &aacute;nh kim đặc trưng. Tuy nhi&ecirc;n, sang tới phối m&agrave;u lần n&agrave;y, Nike lại b&ugrave;ng nổ bằng c&aacute;ch mang đến c&aacute;c phối m&agrave;u rực rỡ, tri &acirc;n những huyền thoại của Mercurial nhưng vẫn giữ n&eacute;t đương đại đầy cuốn h&uacute;t.</p>\r\n<hr />\r\n<div class=\"elfsight-app-fbb3cf8a-c3a2-4c1e-9c9b-cd027da02df5\" data-miwrid=\"a8dc074a-dfd8-41f7-860e-c7a2914f36fb\">\r\n<div id=\"eapps-photo-gallery-fbb3cf8a-c3a2-4c1e-9c9b-cd027da02df5\" class=\"widget__RootComponent-sc-5c2dec5b-0 lgONPl RootLayout__RootComponent-sc eapps-photo-gallery-fbb3cf8a-c3a2-4c1e-9c9b-cd027da02df5-custom-css-root\">\r\n<div class=\"EmbedRoot__Root-sc-615452d5-0 hnFxvH es-embed-root widget__StyledEmbedRoot-sc-5c2dec5b-2 bmFbzV eapp-photo-gallery-photo-gallery-component\">\r\n<div class=\"widget__HeadingContainer-sc-5c2dec5b-1 ffHmuR eapp-photo-gallery-photo-gallery-heading\" style=\"text-align: center;\"><strong>NIKE MERCURIAL</strong></div>\r\n<div>\r\n<div class=\"Masonry__Container-sc-74f10eca-0 daqNnz eapp-photo-gallery-masonry-component\">\r\n<div class=\"ItemGrid__Grid-sc-b8313d44-0 eNUwyX eapp-photo-gallery-item-grid-component\">\r\n<div class=\"MasonryItem__Item-sc-a17d32ab-0 kXgGzo eapp-photo-gallery-masonry-item-item\" style=\"text-align: center;\">\r\n<div class=\"MasonryItem__Content-sc-a17d32ab-1 gBvKHj eapp-photo-gallery-masonry-item-content\">\r\n<div class=\"ItemData__Container-sc-fe2b9e06-4 lfFjav eapp-photo-gallery-item-data-component\" tabindex=\"0\" role=\"button\" aria-label=\"Visit linked content\">\r\n<div class=\"ItemData__ImageContainer-sc-fe2b9e06-5 KVTni eapp-photo-gallery-item-data-imageContainer eapp-photo-gallery-masonry-item-imageContainer\">\r\n<div class=\"ItemData__ImageBackground-sc-fe2b9e06-1 NBKrO eapp-photo-gallery-item-data-imageBackground\">&nbsp;</div>\r\n</div>\r\n<div class=\"WatermarkLogo__Wrapper-sc-98c7adfb-0 jyOHFJ eapp-photo-gallery-item-data-watermarkLogoWrapper\">\r\n<div class=\"WatermarkLogo__LogoContainer-sc-98c7adfb-1 fYgucl eapp-photo-gallery-item-data-watermarkLogo eapp-photo-gallery-item-data-watermarkPosition-undefined\">&nbsp;</div>\r\n</div>\r\n<div class=\"ItemData__InfoWrapper-sc-fe2b9e06-2 dITMsh eapp-photo-gallery-item-data-info\">\r\n<div class=\"Info__Container-sc-13d2405c-0 cSRluY eapp-photo-gallery-info-component\">\r\n<div class=\"Info__Title-sc-13d2405c-1 DwfVd eapp-photo-gallery-info-title\">Mercurial Vapor 16 Pro TF - Trắng/Xanh - FQ8687 - 400</div>\r\n<div class=\"Info__Description-sc-13d2405c-2 hHHVyA eapp-photo-gallery-info-description\">2.520.000đ</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"MasonryItem__Item-sc-a17d32ab-0 kXgGzo eapp-photo-gallery-masonry-item-item\" style=\"text-align: center;\">\r\n<div class=\"MasonryItem__Content-sc-a17d32ab-1 gBvKHj eapp-photo-gallery-masonry-item-content\">\r\n<div class=\"ItemData__Container-sc-fe2b9e06-4 lfFjav eapp-photo-gallery-item-data-component\" tabindex=\"0\" role=\"button\" aria-label=\"Visit linked content\">\r\n<div class=\"ItemData__ImageContainer-sc-fe2b9e0